{
  "where_we_lag": {
    "headline": {
      "text": "In Kanta-Häme, the crude symptomatic treatment share (34.2%) is below the national 39.5%, while the crude share with no treatment record within 12 months (32.1%) is above 27.5% nationally.",
      "claim_ids": [
        "cty:symptomatic:Kanta_Hämeen_hyvinvointialue",
        "nat:symptomatic",
        "cty:no_treatment_record:Kanta_Hämeen_hyvinvointialue",
        "nat:no_treatment_record"
      ]
    },
    "details": [
      {
        "text": "Kanta-Häme's crude share with no treatment record within 12 months is 32.1% (95% CI 28.3–36.1; n=175/546) versus 27.5% (4089/14873) nationally, and its crude symptomatic treatment share is 34.2% (95% CI 30.4–38.3; n=187/546) versus 39.5% (5871/14873) nationally, with these 95% confidence intervals excluding the national values.",
        "claim_ids": [
          "cty:no_treatment_record:Kanta_Hämeen_hyvinvointialue",
          "nat:no_treatment_record",
          "cty:symptomatic:Kanta_Hämeen_hyvinvointialue",
          "nat:symptomatic"
        ]
      },
      {
        "text": "The county's crude curative treatment share is 23.4% (95% CI 20.1–27.2; n=128/546) compared with 27.0% (4009/14873) nationally, and its crude life-prolonging treatment share is 32.2% (95% CI 28.4–36.3; n=176/546) compared with 30.4% (4522/14873) nationally; each 95% confidence interval includes the national value.",
        "claim_ids": [
          "cty:curative:Kanta_Hämeen_hyvinvointialue",
          "nat:curative",
          "cty:life_prolonging:Kanta_Hämeen_hyvinvointialue",
          "nat:life_prolonging"
        ]
      },
      {
        "text": "Public registry data do not report county waiting times, while preliminary, unpublished national figures show 155 days on average from symptoms to treatment in Finland (versus 107 in Sweden and 67 in Denmark), with 56 days of patient delay, 41 days in primary care and 58 days in specialist care.",
        "claim_ids": [
          "bs:coverage:Treatment_start",
          "mot:total_fi",
          "mot:total_se",
          "mot:total_dk",
          "mot:patient",
          "mot:primary",
          "mot:specialist"
        ]
      }
    ]
  },
  "how_sure_are_we": {
    "headline": {
      "text": "Kanta-Häme's crude share with no treatment record within 12 months (32.1% vs 27.5% nationally) is a data-quality signal suggesting lower crude treatment shares may partly reflect unrecorded treatment.",
      "claim_ids": [
        "cty:no_treatment_record:Kanta_Hämeen_hyvinvointialue",
        "nat:no_treatment_record",
        "bs:coverage:Treatment_start"
      ]
    },
    "details": [
      {
        "text": "Because having no treatment record within 12 months (crude 32.1% vs 27.5% nationally) mixes patients who received no treatment and treatment that was not recorded, we infer that Kanta-Häme's lower crude symptomatic share (34.2% vs 39.5%) may partly reflect unrecorded treatment, while a journal article's ~90% HILMO–Cancer Registry match covers diagnoses only.",
        "claim_ids": [
          "cty:no_treatment_record:Kanta_Hämeen_hyvinvointialue",
          "nat:no_treatment_record",
          "cty:symptomatic:Kanta_Hämeen_hyvinvointialue",
          "nat:symptomatic",
          "bs:coverage:Treatment_start",
          "lit:hilmo_90"
        ]
      },
      {
        "text": "County treatment shares are crude (not adjusted for age or stage): stage at diagnosis is missing for ~48% of new patients, and only national age-adjusted curative reference values (26.7% for men and 26.9% for women, digitised from a figure at about ±0.5 percentage points) are available here.",
        "claim_ids": [
          "cty:curative:Kanta_Hämeen_hyvinvointialue",
          "bs:coverage:Diagnosis",
          "q:7885b0974f",
          "k16:curative:men:national",
          "k16:curative:women:national"
        ]
      },
      {
        "text": "Kanta-Häme's crude recorded MDT share of 21.6% (95% CI 18.4–25.3; n=118/546), whose 95% confidence interval excludes the national 6.0% (893/14873), measures recording practice rather than care because HILMO captures specialist procedures only from direct patient contacts.",
        "claim_ids": [
          "cty:mdt_recorded:Kanta_Hämeen_hyvinvointialue",
          "nat:mdt_recorded",
          "bs:coverage:MDT",
          "q:39e6ba43a9"
        ]
      },
      {
        "text": "Public data do not include symptoms, referrals or outpatient primary care visits, do not mention occupational health, capture imaging only indirectly as the diagnosis basis in approximately 20% of cases, and record whether a specialist visit (93.6% nationally within 12 months) or treatment occurred without county waiting times.",
        "claim_ids": [
          "bs:coverage:Symptoms",
          "bs:coverage:Referral",
          "bs:coverage:Primary_care_occupational_health",
          "q:323de0d90d",
          "bs:coverage:Imaging",
          "q:5eb155decc",
          "bs:coverage:First_specialist_visit",
          "bs:coverage:Treatment_start"
        ]
      }
    ]
  },
  "what_to_do_first": {
    "headline": {
      "text": "The team recommends publishing county recording completeness given Kanta-Häme's 32.1% crude no-treatment-record share, reporting access times using THL 21/2016 definitions, and adopting standard referral rules and diagnostic contacts.",
      "claim_ids": [
        "rec:3",
        "cty:no_treatment_record:Kanta_Hämeen_hyvinvointialue",
        "rec:1",
        "rec:2"
      ]
    },
    "details": [
      {
        "text": "Because Kanta-Häme's crude no-treatment-record share is 32.1% (vs 27.5% nationally) and national data reporting and stage coverage (~48% missing) are incomplete, the team recommends publishing county recording completeness for stage, drug treatment and MDT coding while a national quality registry (targeting 90% coverage including stage) and uniform recording instructions are planned.",
        "claim_ids": [
          "rec:3",
          "cty:no_treatment_record:Kanta_Hämeen_hyvinvointialue",
          "nat:no_treatment_record",
          "q:7885b0974f",
          "q:950a2f797b",
          "q:82d365cd2c",
          "q:f07a34a300",
          "q:4a856bd695"
        ]
      },
      {
        "text": "Since the Health Care Act sets no maximum time for a cancer suspicion, the team recommends reporting access times using THL guidance 21/2016 (defining 16 cancers) with handover alerts while the roadmap plans national pathways and target access times in 2026–2028 and the Filha programme's diagnostics recommendation with specialist care time limits is due before the 2030 mid-term evaluation.",
        "claim_ids": [
          "rec:1",
          "law:no_max",
          "thl:21_2016",
          "q:24169121a4",
          "q:b326e35410",
          "q:432c0e51d6",
          "q:614febebf2"
        ]
      },
      {
        "text": "To address referral and diagnostic delays—where a mentor insight notes that a weak referral receives a lower urgency rating—the team recommends a standard referral template and persistent-symptoms rule (modelled on the KYS regional pathway document) plus a named diagnostic contact, while the roadmap plans national referral criteria and care-coordinator guidance in 2026–2028 (for county adoption in 2029–2031).",
        "claim_ids": [
          "rec:2",
          "mentor:kaisa_referral",
          "reg:kys_template",
          "reg:kys_persistent",
          "reg:named_contact",
          "q:c61439b30f",
          "q:abcbb06ae3",
          "q:050ee09ebe"
        ]
      }
    ]
  }
}
